    "content": "<?php\n/**\n * Clutch Arena - Admin Logout\n */\nrequire_once __DIR__ . '/../../config.php';\n\nunset($_SESSION['admin_id']);\nunset($_SESSION['admin_username']);\n\nheader(\"Location: login.php\");\nexit;\n?>\n"
